import{_ as a,a as r}from"./chunks/kefu-telegram.DsQ1DmYg.js";import{_ as e}from"./chunks/kefu-chat.CQaKJK-O.js";import{_ as o,o as i,c as l,a2 as s}from"./chunks/framework.DDY-poMm.js";const f=JSON.parse('{"title":"在线客服","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/customer-service.md","filePath":"zh/guide/customer-service.md","lastUpdated":1790683574000}'),n={name:"zh/guide/customer-service.md"};function p(d,t,c,g,h,m){return i(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="在线客服" tabindex="-1">在线客服 <a class="header-anchor" href="#在线客服" aria-label="Permalink to &quot;在线客服&quot;">​</a></h1><p>用户在 <strong>App 或手机网页里直接和客服聊天</strong>，客服在 <strong>Telegram</strong> 里接待——不需要另装客服软件，也不需要用户有 Telegram 账号。</p><ul><li><strong>一人一会话</strong>：每位用户在 Telegram 客服群里自动拥有一个独立话题，不串号，历史可追溯</li><li><strong>两端同一段对话</strong>：用户在 App 和手机网页看到的是同一段聊天记录，换设备接着聊</li><li><strong>文字与图片都支持</strong>：用户可以发文字、发截图；客服回复的文字、表情、图片实时送达 App</li><li><strong>消息留档</strong>：所有对话都保存在平台自己的系统里，运营可在后台随时查看</li></ul><div class="tip custom-block"><p class="custom-block-title">适用范围</p><p>目前 <strong>App 与手机网页（H5）</strong> 已接入。PC 网页端暂沿用原有的客服窗口。</p></div><h2 id="用户端长什么样" tabindex="-1">用户端长什么样 <a class="header-anchor" href="#用户端长什么样" aria-label="Permalink to &quot;用户端长什么样&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 240px;max-width:240px;"><img src="'+a+'" alt="App 首页客服入口" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>入口</b><br>首页右上角的耳机图标；「我的」页面的「在线客服」也能进 </figcaption></figure><figure style="margin:0;flex:0 0 240px;max-width:240px;"><img src="'+e+'" alt="App 在线客服聊天页" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>聊天页</b><br>左侧是客服，右侧是用户；左下角按钮可发图片 </figcaption></figure></div><p>用户点开就是一个普通聊天页，发出去的消息立即出现在客服的 Telegram 里；客服回复后，App 页面<strong>无需刷新</strong>就能看到。</p><h2 id="客服端长什么样" tabindex="-1">客服端长什么样 <a class="header-anchor" href="#客服端长什么样" aria-label="Permalink to &quot;客服端长什么样&quot;">​</a></h2><p>客服人员只需要一个 Telegram 客户端（手机或电脑都可以）。</p><figure style="margin:32px auto;max-width:520px;"><img src="'+r+'" alt="Telegram 客服群中的用户话题" style="border-radius:10px;border:1px solid var(--vp-c-divider);width:100%;"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"> 客服群里的一个用户话题。话题名是「用户 ID + 账号」，底部可切换不同用户的话题 </figcaption></figure><ul><li>用户<strong>第一次</strong>发消息时，客服群里会<strong>自动新建一个话题</strong>，话题名为「用户 ID 账号名」（如 <code>391 test001</code>），一眼知道是谁</li><li>客服<strong>直接在该话题里回复</strong>即可，回复会送到对应用户的 App</li><li>客服可以回文字、表情、图片；语音和文件不会转发到 App</li><li>多名客服可以同时在群里，谁有空谁接</li></ul><div class="warning custom-block"><p class="custom-block-title">隐私保护</p><p>用户消息在转发到 Telegram 之前，身份证号、银行卡号、手机号等敏感信息会<strong>自动脱敏</strong>；平台自己的系统里保留原文，需要时可在后台查看。</p></div><h2 id="后台查看会话记录" tabindex="-1">后台查看会话记录 <a class="header-anchor" href="#后台查看会话记录" aria-label="Permalink to &quot;后台查看会话记录&quot;">​</a></h2><p>后台「<strong>客服会话记录</strong>」页面可以按用户 ID 查询会话，查看完整的聊天历史（时间、来自谁、内容）。这是<strong>只读</strong>的取证与复核页面——回复用户仍然在 Telegram 里进行。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><p>该页面需要单独授权给客服/运营角色，未授权的账号看不到这个菜单。角色授权方法见<a href="/CoinExchange/zh/guide/admin-login">后台登录与权限</a>。</p></div><h2 id="如何开通" tabindex="-1">如何开通 <a class="header-anchor" href="#如何开通" aria-label="Permalink to &quot;如何开通&quot;">​</a></h2><p>整个开通过程不需要技术方介入，运营自己在 Telegram 与后台完成。按顺序做，<strong>每一步都不能省</strong>。</p><h3 id="第-1-步-建客服群并开启「话题」" tabindex="-1">第 1 步：建客服群并开启「话题」 <a class="header-anchor" href="#第-1-步-建客服群并开启「话题」" aria-label="Permalink to &quot;第 1 步：建客服群并开启「话题」&quot;">​</a></h3><p>在 Telegram 新建一个群组，进入群设置将其升级为<strong>超级群</strong>，并打开 <strong>「话题（Topics）」</strong> 功能。</p><div class="danger custom-block"><p class="custom-block-title">必须是开了话题的超级群</p><p>配成私聊或普通群，用户发的消息会送不出去。这是开通失败最常见的原因。</p></div><h3 id="第-2-步-新建一个专用的客服机器人" tabindex="-1">第 2 步：新建一个专用的客服机器人 <a class="header-anchor" href="#第-2-步-新建一个专用的客服机器人" aria-label="Permalink to &quot;第 2 步：新建一个专用的客服机器人&quot;">​</a></h3><p>通过 Telegram 的 @BotFather 创建一个<strong>新的</strong>机器人，记下它的 Token。</p><div class="danger custom-block"><p class="custom-block-title">不能复用充提告警机器人</p><p>如果平台已经在用 Telegram 机器人接收充值/提现告警，客服<strong>必须另建一个机器人</strong>。一个机器人只能被一套系统使用，共用会导致两边互相抢消息、都收不全。</p></div><h3 id="第-3-步-把机器人拉进群并授权" tabindex="-1">第 3 步：把机器人拉进群并授权 <a class="header-anchor" href="#第-3-步-把机器人拉进群并授权" aria-label="Permalink to &quot;第 3 步：把机器人拉进群并授权&quot;">​</a></h3><p>把机器人加入客服群，设为<strong>管理员</strong>，并在管理员权限里<strong>单独勾选「管理话题（Manage Topics）」</strong>。</p><div class="warning custom-block"><p class="custom-block-title">只设管理员不够</p><p>「管理话题」是一个独立的权限开关，默认不勾。没有它，机器人无法为新用户建话题，表现就是用户发消息后群里没有任何动静。</p></div><h3 id="第-4-步-在后台填写配置" tabindex="-1">第 4 步：在后台填写配置 <a class="header-anchor" href="#第-4-步-在后台填写配置" aria-label="Permalink to &quot;第 4 步：在后台填写配置&quot;">​</a></h3><p>进入后台「<strong>第三方配置 → 在线客服</strong>」，填写：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>开启在线客服</td><td>总开关。打开后 App / H5 的所有客服入口都走这套系统</td></tr><tr><td>客服机器人 Token</td><td>第 2 步拿到的 Token</td></tr><tr><td>客服群组 ID</td><td>第 1 步建的群的 ID，通常以 <code>-100</code> 开头</td></tr><tr><td>回调地址</td><td>平台接收 Telegram 消息的地址，由技术方提供</td></tr><tr><td>回调密钥</td><td>用于校验回调来源的一串密文，由技术方提供或自行设定</td></tr></tbody></table><p>保存时，系统会自动把回调地址登记到 Telegram，之后客服在群里的回复才会回到 App。</p><div class="warning custom-block"><p class="custom-block-title">「保存成功」不代表已生效</p><p>只有当<strong>开关打开、且 Token / 回调地址 / 回调密钥三项都填了</strong>，系统才会去 Telegram 登记回调。缺任何一项，界面照样提示保存成功，但客服回复不会回到 App。排查问题时先来核对这四项。</p></div><h3 id="第-5-步-用测试账号验证" tabindex="-1">第 5 步：用测试账号验证 <a class="header-anchor" href="#第-5-步-用测试账号验证" aria-label="Permalink to &quot;第 5 步：用测试账号验证&quot;">​</a></h3><ol><li>用一个测试账号在 App 里打开客服，发一条消息</li><li>客服群里应立刻出现一个以该账号命名的新话题，里面是这条消息</li><li>在话题里回一句</li><li>App 的聊天页应在一两秒内显示这条回复，<strong>不用刷新</strong></li></ol><p>四步都通过，即可对外使用。</p><h2 id="关闭或回退" tabindex="-1">关闭或回退 <a class="header-anchor" href="#关闭或回退" aria-label="Permalink to &quot;关闭或回退&quot;">​</a></h2><p>把「开启在线客服」开关关掉即可。关掉后：</p><ul><li>App 与 H5 的客服入口会<strong>回落到原来的外部链接客服</strong>（那套配置仍保留在后台「客服设置」里，未被删除）</li><li>已产生的会话记录不会丢失，重新打开开关后继续可用</li></ul><div class="tip custom-block"><p class="custom-block-title">改完配置后</p><p>与其他后台配置一样，App 用户需要<strong>完全退出 App 再打开</strong>才会拿到新的开关状态；手机网页刷新即可。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="用户发了消息-客服群里没动静" tabindex="-1">用户发了消息，客服群里没动静？ <a class="header-anchor" href="#用户发了消息-客服群里没动静" aria-label="Permalink to &quot;用户发了消息，客服群里没动静？&quot;">​</a></h3><p>按顺序排查：</p><ol><li>后台「开启在线客服」是否打开</li><li>「客服群组 ID」填的是不是<strong>开了话题的超级群</strong>——填成私聊或普通群是最常见的错法</li><li>机器人是否在群里、是否为管理员、<strong>「管理话题」权限是否单独勾选</strong></li></ol><h3 id="用户的消息到群里了-客服回复却回不到-app" tabindex="-1">用户的消息到群里了，客服回复却回不到 App？ <a class="header-anchor" href="#用户的消息到群里了-客服回复却回不到-app" aria-label="Permalink to &quot;用户的消息到群里了，客服回复却回不到 App？&quot;">​</a></h3><p>说明消息进得去、回不来，问题在回调这一段：</p><ol><li>「回调地址」「回调密钥」是否都填了（缺一项系统不会去登记回调）</li><li>填完后是否<strong>重新保存</strong>过一次（登记动作发生在保存时）</li><li>客服是否在<strong>用户对应的话题</strong>里回复，而不是在群的「General」里</li></ol><h3 id="客服发了语音-文件-用户说没收到" tabindex="-1">客服发了语音 / 文件，用户说没收到？ <a class="header-anchor" href="#客服发了语音-文件-用户说没收到" aria-label="Permalink to &quot;客服发了语音 / 文件，用户说没收到？&quot;">​</a></h3><p>目前只转发<strong>文字、表情和图片</strong>。语音和文件不会送到 App，请改用文字或截图。</p><h3 id="一个用户会不会出现多个话题" tabindex="-1">一个用户会不会出现多个话题？ <a class="header-anchor" href="#一个用户会不会出现多个话题" aria-label="Permalink to &quot;一个用户会不会出现多个话题？&quot;">​</a></h3><p>不会。每个用户只对应一个话题，无论他从 App 还是手机网页发起，都是同一个。</p>',49)])])}const v=o(n,[["render",p]]);export{f as __pageData,v as default};
